 const app=client();await app.start();const conversation=nativeFixture(app);conversation.kind='group';conversation.capabilities={canLeave:true};await app.api.openNativeConversation(nativeId);let left=false;app.server.replies.set('/api/messages/conversations/'+nativeId+'/leave',()=>{left=true;return app.response({left:true});});app.server.replies.set('/api/messages/conversations',()=>app.response({conversations:left?[]:[conversation]}));app.api.action('native-leave-group');assert.ok(!app.calls.some(c=>c.url.endsWith('/leave')));await app.api.submit(app.form('native-group-leave',{}, {conversation:nativeId}));assert.equal(left,true);assert.equal(app.api.state.nativeId,null);assert.equal(app.api.state.nativeConversations.length,0);
