function mockEncrypted(app,extra={}){const messenger={status:()=>({phase:'ready',userId:'@native:matrix.example',deviceId:'dedicated-device'}),connect:async()=>{},disconnect:async()=>({locked:true,revocation:'confirmed'}),listRooms:async()=>[],listInvitations:async()=>[],timeline:async()=>[],devices:async()=>[],...extra};Object.assign(app.api.state,{secure:messenger,secureStatus:messenger.status()});return messenger;}
test('normal encrypted enrollment asks only for the ordinary account password and keeps callbacks alive across routes',async()=>{
 const app=client();await app.start();app.server.replies.set('/api/encryption/config',app.response({configured:true,provider:'synapse-jwt',homeserver:'https://matrix.example',nativePasswordAvailable:true}));let callbacks,enrollment;const messenger=mockEncrypted(app);app.api.state.secure=null;app.api.state.secureStatus=null;app.window.VoidSecureMessenger={create:options=>{callbacks=options;return messenger;},async enrollEncryptedMessaging(options){enrollment=options;const created=options.createSecureMessenger({onState:options.onState});options.onReauthenticated({reauthenticatedAt:123});await created.connect();return{messenger:created,session:{userId:'@native:matrix.example',deviceId:'dedicated-device'},resumed:true};}};await app.api.secureConnect();const html=app.nodes.get('home-enrollment-body').innerHTML;assert.match(html,/Voidline account password/);assert.doesNotMatch(html,/name="accessToken"|name="storagePassword"/);await app.api.submit(app.form('secure-enroll',{password:'A native password for unlock'}));assert.equal(enrollment.accountId,'account-a');assert.equal(enrollment.password,'A native password for unlock');assert.equal(app.api.state.session.reauthenticatedAt,123);assert.doesNotMatch(JSON.stringify(app.api.state),/A native password for unlock/);app.api.state.generation++;callbacks.onState({phase:'ready',userId:'@native:matrix.example',deviceId:'changed-after-navigation'});assert.equal(app.api.state.secureStatus.deviceId,'changed-after-navigation');app.api.state.account={...app.api.state.account,id:'another-account'};callbacks.onState({phase:'ready',deviceId:'wrong-account'});assert.equal(app.api.state.secureStatus.deviceId,'changed-after-navigation');
});
