test('several Standard messages queue while the first round trip is pending and keep input available',async()=>{
 const app=client();await app.start();await openConsentedNative(app);const held=deferred(),sent=[];app.server.replies.set('/api/messages/conversations/'+nativeId+'/messages',async request=>{const body=JSON.parse(request.body);sent.push(body);if(sent.length===1)await held.promise;return app.response({message:{...nativeMessage('sent-'+sent.length,sent.length,body.text),author_id:'account-a'}},201);});const form=app.form('native-message');app.nodes.get('home-native-input').value='First';const first=app.api.submit(form);await until(()=>sent.length===1);app.nodes.get('home-native-input').value='Second';const second=app.api.submit(form);await until(()=>app.api.nativeQueue().filter(item=>item.status==='queued').length===1);assert.equal(app.api.nativeDraft().enqueueBusy,false);assert.equal(app.nodes.get('home-native-input').value,'');assert.equal(sent.length,1);held.resolve();await Promise.all([first,second]);assert.deepEqual(sent.map(item=>item.text),['First','Second']);assert.equal(new Set(sent.map(item=>item.clientId)).size,2);assert.equal(app.api.state.nativeMessages.length,2);
});
