test('password changes prepare encrypted credentials before transport and commit only after acknowledgment',async()=>{
 const app=client();await app.start();const events=[],prepared=deferred();app.window.VoidSecureMessenger={prepareEncryptedPasswordChange:async options=>{events.push('prepare');assert.equal(options.accountId,'account-a');await prepared.promise;return{commit:async()=>events.push('commit'),abort:async()=>events.push('abort'),retain:async()=>events.push('retain')};}};app.server.replies.set('/api/auth/password/change',()=>{events.push('server');return app.response({account:app.server.account,session:{id:'new'},csrfToken:'new-csrf'});});const changing=app.api.submit(app.form('password-change',{currentPassword:'current long password',newPassword:'new long password',passwordConfirm:'new long password'}));await until(()=>events.length===1);assert.deepEqual(events,['prepare']);assert.ok(!app.calls.some(call=>call.url==='/api/auth/password/change'));prepared.resolve();await changing;assert.deepEqual(events,['prepare','server','commit']);assert.equal(app.api.state.session.id,'new');
});
