 for(const change of['account','session','generation','dialog']){const app=client();await app.start();const events=[],prepared=deferred();let isCurrent;app.window.VoidSecureMessenger={prepareEncryptedPasswordChange:async options=>{isCurrent=options.isCurrent;events.push('prepare');await prepared.promise;return{commit:async()=>events.push('commit'),abort:async()=>events.push('abort'),retain:async()=>events.push('retain')};}};const changing=app.api.submit(app.form('password-change',{currentPassword:'current long password',newPassword:'new long password',passwordConfirm:'new long password'}));await until(()=>events.length===1);assert.equal(isCurrent(),true);if(change==='account')app.api.state.account={...app.server.account,id:'another-account'};if(change==='session')app.api.state.session={...app.api.state.session,id:'newer-session'};if(change==='generation')app.api.state.generation++;if(change==='dialog')app.api.showDialog('Current profile','','<p>Preserve newer view</p>');assert.equal(isCurrent(),false);prepared.resolve();await changing;assert.deepEqual(events,['prepare','abort'],change);assert.ok(!app.calls.some(call=>call.url==='/api/auth/password/change'),change);}
