 const app=client();await app.start();const prepared=[deferred(),deferred()],events=[];let index=0;app.window.VoidSecureMessenger={prepareEncryptedPasswordChange:async()=>{const id=index++;events.push('prepare'+id);await prepared[id].promise;return{commit:async()=>events.push('commit'+id),abort:async()=>events.push('abort'+id),retain:async()=>events.push('retain'+id)};}};app.server.replies.set('/api/auth/password/change',app.response({account:app.server.account,session:{id:'new'},csrfToken:'new-csrf'}));const fields={currentPassword:'current long password',newPassword:'new long password',passwordConfirm:'new long password'};const older=app.api.submit(app.form('password-change',fields));await until(()=>index===1);const newer=app.api.submit(app.form('password-change',fields));await until(()=>index===2);prepared[0].resolve();await older;assert.equal(app.api.state.credentialsBusy,true);assert.ok(events.includes('abort0'));assert.ok(!app.calls.some(call=>call.url==='/api/auth/password/change'));prepared[1].resolve();await newer;assert.equal(app.api.state.credentialsBusy,false);assert.ok(events.includes('commit1'));
